"""
Module for managing packages in qBraid environments.

All functions use env_id (not slug) to identify environments,
since env_id is the unique local identifier. Same slug can be
installed multiple times with different env_ids.
"""

import logging
import os
import subprocess
import sys
from pathlib import Path
from typing import Callable, Optional

from qbraid_core.system.executables import python_paths_equivalent
from qbraid_core.system.packages import set_include_sys_site_pkgs_value

from .exceptions import EnvironmentNotFoundError, EnvironmentOperationError
from .paths import find_python_in_env
from .registry import EnvironmentRegistryManager

# When an install fails, keep this much of the *tail* of the combined pip output
# so callers can surface the actual error to the user, instead of only the last
# line (which is frequently an unhelpful "hint: See above for details.").
_MAX_FAILURE_OUTPUT_CHARS = 6000


def _tail(text: str, limit: int = _MAX_FAILURE_OUTPUT_CHARS) -> str:
    """Return the last `limit` characters of `text` (stripped), flagging any cut."""
    text = (text or "").strip()
    if len(text) <= limit:
        return text
    return "…(earlier output truncated)…\n" + text[-limit:]


logger = logging.getLogger(__name__)


def _get_env_python(env_id: str) -> tuple[Path, str]:
    """Get environment path and python executable for env_id.

    Args:
        env_id: Environment ID (local registry identifier)

    Returns:
        tuple[Path, str]: (env_path, python_executable)

    Raises:
        EnvironmentNotFoundError: If env_id not found in registry
        EnvironmentOperationError: If python executable not found
    """
    registry = EnvironmentRegistryManager()
    result = registry.find_by_env_id(env_id)

    if result is None:
        raise EnvironmentNotFoundError(
            f"Environment '{env_id}' not found in registry. "
            "Use env_id (not slug) for local operations."
        )

    _, entry = result
    env_path = entry.path

    if not env_path.exists():
        raise EnvironmentNotFoundError(f"Environment path does not exist: {env_path}")

    # Use python_executable from registry if available, otherwise detect
    python_exe = None
    if entry.python_executable and Path(entry.python_executable).exists():
        python_exe = str(entry.python_executable)
    else:
        python_exe = find_python_in_env(env_path)

    if python_exe is None:
        raise EnvironmentOperationError(
            f"Could not find valid Python executable in environment: {env_path}"
        )

    return env_path, python_exe


def pip_install(
    env_id: str,
    packages: list[str],
    upgrade_pip: bool = False,
    progress_callback: Optional[Callable[[str, int, int], None]] = None,
) -> dict:
    """Install packages into an environment.

    Args:
        env_id: Environment ID (local registry identifier, NOT slug)
        packages: List of packages to install (e.g., ["numpy", "pandas>=1.0"])
        upgrade_pip: If True, upgrade pip before installing packages
        progress_callback: Optional callback for progress reporting.
            Called with (stage, completed, total) where stage is one of:
            - "prepare": Setting up for installation
            - "install": Installing packages (completed = packages collected so far)
            - "registry": Updating registry after install

    Returns:
        dict: Result with 'success', 'message', and 'output' keys

    Raises:
        EnvironmentNotFoundError: If env_id not found in registry
        EnvironmentOperationError: If installation fails

    Example:
        >>> pip_install("abc123", ["numpy", "pandas"])
        {'success': True, 'message': 'Installed 2 packages', 'output': '...'}

        >>> def on_progress(stage, completed, total):
        ...     print(f"{stage}: {completed}/{total}")
        >>> pip_install("abc123", ["numpy"], progress_callback=on_progress)
    """
    total_packages = len(packages)

    if not packages and not upgrade_pip:
        return {"success": True, "message": "No packages provided", "output": ""}

    if progress_callback:
        progress_callback("prepare", 0, total_packages)

    env_path, python = _get_env_python(env_id)
    output_messages = []

    # Upgrade pip if requested
    if upgrade_pip:
        logger.info("Upgrading pip in environment %s", env_id)
        result = subprocess.run(
            [python, "-m", "pip", "install", "--upgrade", "pip"],
            capture_output=True,
            check=False,
        )
        stderr = result.stderr.decode("utf-8")
        stdout = result.stdout.decode("utf-8")
        output_messages.append(stderr + stdout.strip().split("\n")[-1])

    if not packages:
        return {
            "success": True,
            "message": "Upgraded pip",
            "output": " ".join(output_messages),
        }

    # Write packages to temp requirements file
    reqs_tmp = env_path / "reqs_tmp.txt"
    with open(reqs_tmp, "w", encoding="utf-8") as f:
        for package in packages:
            f.write(package + "\n")

    install_command = [python, "-m", "pip", "install", "-r", str(reqs_tmp)]

    try:
        # Temporarily disable system site packages during install so pip
        # installs into the venv's site-packages, not system.  We save the
        # original value and restore it after install completes.
        is_system_python = python_paths_equivalent(python, sys.executable)
        _original_sys_site = None

        if not is_system_python:
            cfg = env_path / "pyenv" / "pyvenv.cfg"
            if cfg.exists():
                # Read current value before overriding
                cfg_text = cfg.read_text()
                _original_sys_site = (
                    "true"
                    in cfg_text.lower().split("include-system-site-packages")[-1].split("\n")[0]
                    if "include-system-site-packages" in cfg_text
                    else False
                )
                set_include_sys_site_pkgs_value(False, str(cfg))

        if progress_callback:
            progress_callback("install", 0, total_packages)

        # Run pip install with streaming output for progress tracking
        logger.info("Installing packages in environment %s: %s", env_id, packages)

        if progress_callback:
            # Use Popen to stream output and track progress
            collected_count = 0
            full_output = []

            process = subprocess.Popen(
                install_command,
                stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT,
                text=True,
                bufsize=1,
            )

            if process.stdout is not None:
                for line in iter(process.stdout.readline, ""):
                    full_output.append(line)
                    # Track "Collecting package" lines for progress
                    if line.startswith("Collecting "):
                        collected_count += 1
                        progress_callback(
                            "install", min(collected_count, total_packages), total_packages
                        )

            process.wait()
            returncode = process.returncode
            output_text = "".join(full_output)
            if returncode == 0:
                output_messages.append(
                    output_text.strip().rsplit("\n", maxsplit=1)[-1] if output_text.strip() else ""
                )
            else:
                # On failure keep the (tail-capped) full output so the caller
                # can show the user WHY it failed — not just the last line.
                output_messages.append(_tail(output_text))
        else:
            # Simple run without progress tracking
            result = subprocess.run(install_command, capture_output=True, check=False)
            returncode = result.returncode
            stderr = result.stderr.decode("utf-8")
            stdout = result.stdout.decode("utf-8")
            if returncode == 0:
                output_messages.append(stderr + stdout.strip().split("\n")[-1])
            else:
                output_messages.append(_tail(stderr + "\n" + stdout))

        # Restore system site packages to original value
        if not is_system_python and _original_sys_site is not None:
            cfg = env_path / "pyenv" / "pyvenv.cfg"
            if cfg.exists():
                set_include_sys_site_pkgs_value(_original_sys_site, str(cfg))

        success = returncode == 0
        message = f"Installed {len(packages)} package(s)" if success else "Installation failed"

        # Update registry with new packages if successful
        if success:
            if progress_callback:
                progress_callback("registry", 0, 1)
            update_registry_packages(env_id)
            if progress_callback:
                progress_callback("registry", 1, 1)

        return {
            "success": success,
            "message": message,
            "output": " ".join(output_messages),
            "returncode": returncode,
        }

    finally:
        # Clean up temp file
        if reqs_tmp.exists():
            try:
                os.remove(reqs_tmp)
            except OSError as err:
                logger.warning("Could not remove temp file %s: %s", reqs_tmp, err)


def pip_uninstall(env_id: str, packages: list[str]) -> dict:
    """Uninstall packages from an environment.

    Args:
        env_id: Environment ID (local registry identifier, NOT slug)
        packages: List of packages to uninstall

    Returns:
        dict: Result with 'success', 'message', and 'output' keys

    Raises:
        EnvironmentNotFoundError: If env_id not found in registry
        EnvironmentOperationError: If uninstallation fails

    Example:
        >>> pip_uninstall("abc123", ["numpy"])
        {'success': True, 'message': 'Uninstalled 1 packages', 'output': '...'}
    """
    if not packages:
        return {"success": True, "message": "No packages provided", "output": ""}

    _env_path, python = _get_env_python(env_id)

    command = [python, "-m", "pip", "uninstall", "-y"] + packages

    logger.info("Uninstalling packages from environment %s: %s", env_id, packages)
    result = subprocess.run(command, capture_output=True, check=False)

    stderr = result.stderr.decode("utf-8")
    stdout = result.stdout.decode("utf-8")
    output = stderr + stdout.strip().split("\n")[-1]

    success = result.returncode == 0
    message = f"Uninstalled {len(packages)} package(s)" if success else "Uninstallation failed"

    # Update registry with new packages if successful
    if success:
        update_registry_packages(env_id)

    return {
        "success": success,
        "message": message,
        "output": output,
        "returncode": result.returncode,
    }


def update_registry_packages(env_id: str) -> None:
    """Update registry with current packages from pip freeze.

    Only stores locally installed packages (not inherited from system site-packages)
    since those are the only packages that can be managed in this environment.

    Args:
        env_id: Environment ID
    """
    try:
        # Record only packages actually installed in this environment, not those
        # inherited from system site-packages. (Recording inherited base-image
        # packages would bloat the registry/manifest and, on publish + recreate,
        # try to pip-install the whole base set — slow and fragile.)
        packages = pip_freeze(env_id, system_site_packages=False)
        pkg_dict = {}
        for pkg in packages:
            if "==" in pkg:
                name, version = pkg.split("==", 1)
                # Strip 'v' prefix from version if present (e.g., v6.1.1 -> 6.1.1)
                if version.startswith("v") and len(version) > 1:
                    version = version[1:]
                pkg_dict[name] = version
            else:
                # Package without version (editable, etc.)
                pkg_dict[pkg] = ""

        registry = EnvironmentRegistryManager()

        # Anti-wipe guard (qBraid/qbraid-core#207): a freeze that disables
        # system-site can return 0 packages for an env configured with
        # include-system-site-packages=true. Never let an empty result overwrite
        # a populated registry list — that empty list would otherwise be pushed
        # to the cloud on the next upload/sync, silently dropping the packages.
        if not pkg_dict:
            found = registry.find_by_env_id(env_id)
            existing = getattr(found[1], "python_packages", None) if found else None
            if existing:
                logger.warning(
                    "pip freeze returned 0 packages for %s; keeping existing "
                    "%d-package registry list instead of wiping it",
                    env_id,
                    len(existing),
                )
                return

        registry.update_environment(env_id, python_packages=pkg_dict)
        logger.debug("Updated registry packages for environment %s", env_id)
    except Exception as err:  # pylint: disable=broad-exception-caught
        logger.warning("Failed to update registry packages for %s: %s", env_id, err)


_update_registry_packages = update_registry_packages  # deprecated alias


def pip_freeze(env_id: str, system_site_packages: bool = True) -> list[str]:
    """Get list of installed packages in an environment (pip freeze).

    Args:
        env_id: Environment ID (local registry identifier, NOT slug)
        system_site_packages: If True, include system site packages in output

    Returns:
        list[str]: List of installed packages in "package==version" format

    Raises:
        EnvironmentNotFoundError: If env_id not found in registry
        EnvironmentOperationError: If pip freeze fails

    Example:
        >>> pip_freeze("abc123")
        ['numpy==1.24.0', 'pandas==2.0.0', ...]
    """
    env_path, python = _get_env_python(env_id)

    # Handle system site packages setting
    # Only disable system site packages if explicitly requested (system_site_packages=False)
    # Save original value so we can restore it exactly.
    is_system_python = python_paths_equivalent(python, sys.executable)
    cfg = env_path / "pyenv" / "pyvenv.cfg"
    _original_sys_site = None

    if not system_site_packages and not is_system_python and cfg.exists():
        # Read current value before overriding
        try:
            cfg_text = cfg.read_text()
            for line in cfg_text.splitlines():
                if line.strip().startswith("include-system-site-packages"):
                    _original_sys_site = "true" in line.split("=", 1)[1].strip().lower()
                    break
            if _original_sys_site is None:
                _original_sys_site = False
        except OSError:
            _original_sys_site = False
        set_include_sys_site_pkgs_value(False, str(cfg))

    try:
        logger.debug("Running pip freeze for environment %s", env_id)
        result = subprocess.run(
            [python, "-m", "pip", "freeze"],
            capture_output=True,
            check=False,
        )

        if result.returncode != 0:
            stderr = result.stderr.decode("utf-8")
            raise EnvironmentOperationError(f"pip freeze failed: {stderr}")

        stdout = result.stdout.decode("utf-8")
        packages = [line.strip() for line in stdout.splitlines() if line.strip()]

        # Process package lines to normalize format
        normalized = []
        for pkg in packages:
            processed = _process_freeze_line(pkg)
            if processed:
                normalized.append(processed)

        return normalized

    finally:
        # Restore system site packages to original value
        if _original_sys_site is not None:
            set_include_sys_site_pkgs_value(_original_sys_site, str(cfg))


def _process_freeze_line(line: str) -> Optional[str]:
    """Process a pip freeze output line to normalize format.

    Args:
        line: Raw line from pip freeze

    Returns:
        str or None: Normalized "package==version" format or None if invalid
    """
    line = line.strip()
    if not line:
        return None

    # Handle "package @ file://..." format
    if " @ " in line:
        package = line.split(" @ ")[0].strip()
        if not package:
            return None
        # Try to extract version from the URL or return package name only
        return package

    # Handle editable installs "-e git+..."
    if line.startswith("-e"):
        if "egg=" in line:
            package = line.split("egg=")[-1].strip()
            return package
        return None

    # Normal "package==version" format
    if "==" in line:
        return line

    return None


def set_system_site_packages(env_id: str, enabled: bool) -> dict:
    """Toggle system site-packages for an environment.

    When enabled, the environment inherits packages from the parent Python
    (e.g., /opt/conda). When disabled, the environment is fully isolated.

    Args:
        env_id: Environment ID (local registry identifier)
        enabled: True to enable, False to disable

    Returns:
        dict with 'success', 'message', and 'enabled' keys

    Raises:
        EnvironmentNotFoundError: If env_id not found in registry
        EnvironmentOperationError: If the operation fails
    """
    env_path, _ = _get_env_python(env_id)
    cfg = env_path / "pyenv" / "pyvenv.cfg"

    if not cfg.exists():
        raise EnvironmentOperationError(
            f"pyvenv.cfg not found at {cfg}. Is this a valid virtual environment?"
        )

    try:
        set_include_sys_site_pkgs_value(enabled, str(cfg))
    except Exception as err:
        raise EnvironmentOperationError(
            f"Failed to update system site-packages setting: {err}"
        ) from err

    status = "enabled" if enabled else "disabled"
    return {
        "success": True,
        "message": f"System site-packages {status} for environment '{env_id}'",
        "enabled": enabled,
    }


def get_system_site_packages(env_id: str) -> bool:
    """Check if system site-packages is enabled for an environment.

    Args:
        env_id: Environment ID (local registry identifier)

    Returns:
        True if system site-packages is enabled, False otherwise

    Raises:
        EnvironmentNotFoundError: If env_id not found in registry
    """
    env_path, _ = _get_env_python(env_id)
    cfg = env_path / "pyenv" / "pyvenv.cfg"

    if not cfg.exists():
        return False

    try:
        content = cfg.read_text()
        for line in content.splitlines():
            if line.strip().startswith("include-system-site-packages"):
                return "true" in line.split("=", 1)[1].strip().lower()
    except (OSError, IndexError):
        pass

    return False


def parse_requirements_file(file_path: str) -> dict[str, str]:
    """Parse a requirements.txt file into a dict of {package: version_spec}.

    Args:
        file_path: Path to requirements.txt file.

    Returns:
        Dict mapping package names to version specifiers
        (e.g., ``{"numpy": "==1.24.0", "requests": ""}``).

    Raises:
        ValueError: If the requirements file does not exist.
    """
    packages = {}
    path = Path(file_path)
    if not path.exists():
        raise ValueError(f"Requirements file not found: {file_path}")

    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            # Skip comments and empty lines
            if not line or line.startswith("#") or line.startswith("-"):
                continue
            # Parse package==version, package>=version, etc.
            for op in ["==", ">=", "<=", "~=", ">", "<"]:
                if op in line:
                    name, version = line.split(op, 1)
                    packages[name.strip()] = f"{op}{version.strip()}"
                    break
            else:
                # No version specifier
                packages[line.strip()] = ""

    return packages
